function normalizeTitle(s) {
  return (s || "")
    .toLowerCase()
    .replace(/\.[a-z0-9]+$/i, "")
    .replace(/_mastered$/i, "")
    .replace(/_devine$/i, "")
    .replace(/[_\-]+/g, " ")
    .replace(/[^a-z0-9àáâãäåæçèéêëìíîïñòóôõöøùúûüýÿœ\s]/gi, "")
    .replace(/\s+/g, " ")
    .trim();
}

function findLyricsForFilename(name) {
  const n = normalizeTitle(name);
  if (!n) return null;
  let best = null;
  let bestScore = 0;
  // 1) Exact / contains on DB title keys
  for (const key of Object.keys(LYRICS_DB)) {
    const k = normalizeTitle(key);
    if (!k) continue;
    if (n === k) return LYRICS_DB[key];
    if (n.includes(k) || k.includes(n)) {
      const score = Math.min(n.length, k.length) / Math.max(n.length, k.length);
      if (score > bestScore) { bestScore = score; best = LYRICS_DB[key]; }
    }
  }
  // 2) Match keys: line inside sheet header
  for (const key of Object.keys(LYRICS_DB)) {
    const sheet = LYRICS_DB[key] || "";
    const m = sheet.match(/Match keys:\s*(.+)/i);
    if (!m) continue;
    const keys = m[1].split(",").map(s => normalizeTitle(s)).filter(Boolean);
    for (const k of keys) {
      if (n === k) return sheet;
      if (n.includes(k) || k.includes(n)) {
        const score = Math.min(n.length, k.length) / Math.max(n.length, k.length);
        if (score > bestScore) { bestScore = score; best = sheet; }
      }
    }
  }
  // 3) Fuzzy token overlap on titles
  if (!best || bestScore < 0.85) {
    const tokens = new Set(n.split(" ").filter(t => t.length > 2));
    for (const key of Object.keys(LYRICS_DB)) {
      const k = normalizeTitle(key);
      const kt = k.split(" ").filter(t => t.length > 2);
      if (!kt.length) continue;
      const hit = kt.filter(t => tokens.has(t)).length;
      const score = hit / kt.length;
      if (score >= 0.6 && score > bestScore) { bestScore = score; best = LYRICS_DB[key]; }
    }
  }
  return best;
}

