$("btnPlay").onclick = async () => {
  try {
    ensureCtx();
    try { await audioCtx.resume(); } catch (e) {}
    if (mode === "B") {
      const aB = $("audioB");
      try { stopLive(); } catch (e) {}
      if (!aB || !aB.src) {
        if ($("status")) $("status").textContent = "No master on B — run MASTER";
        return;
      }
      if (aB.paused) {
        try { applyLiveParams(); } catch (e) {}
        window.__wantPlay = true;
        try {
          await aB.play();
          if ($("btnPlay")) $("btnPlay").textContent = "⏸";
        } catch (e) {
          window.__wantPlay = false;
          if ($("status")) $("status").textContent = "B play failed: " + (e.message || e);
        }
      } else {
        window.__wantPlay = false;
        aB.loop = false;
        aB.pause();
        if ($("btnPlay")) $("btnPlay").textContent = "▶";
      }
      return;
    }
    if (!decodedBuffer) {
      if ($("status")) $("status").textContent = "Load a file first";
      const f = $("file"); if (f) f.click();
      return;
    }
    if (live.playing) {
      window.__wantPlay = false;
      live.offset = livePosition();
      stopLive();
      if ($("btnPlay")) $("btnPlay").textContent = "▶";
      if ($("status")) $("status").textContent = "Paused";
    } else {
      window.__wantPlay = true;
      if (!live.hpf || !live.bands) buildLiveGraph();
      startLive(live.offset || 0);
      if ($("btnPlay")) $("btnPlay").textContent = "⏸";
      if ($("status")) $("status").textContent = "Live A — EQ / vol update in real time";
    }
  } catch (e) {
    console.error(e);
    if ($("status")) $("status").textContent = "Play error: " + (e.message || e);
  }
};

