/* —— EQ spectrum analyzer —— */
const specCanvas = $("eqSpectrum");
let specCtx = null;
try { if (specCanvas && specCanvas.getContext) specCtx = specCanvas.getContext("2d"); } catch (e) { specCtx = null; }
let specData = null;

function resizeSpectrum() {
  if (!specCanvas) return;
  const w = specCanvas.parentElement ? specCanvas.parentElement.clientWidth : 400;
  specCanvas.width = Math.max(200, w);
  specCanvas.height = 44;
}
window.addEventListener("resize", resizeSpectrum);
setTimeout(resizeSpectrum, 50);

function drawSpectrum() {
  // Guard: never touch const before init; also safe if canvas missing
  if (typeof specCtx === "undefined" || !specCtx || !specCanvas) return;
  const w = specCanvas.width, h = specCanvas.height;
  specCtx.clearRect(0, 0, w, h);
  // background
  specCtx.fillStyle = "rgba(8,8,12,0.25)";
  specCtx.fillRect(0, 0, w, h);

  let analyser = null;
  if (live.playing && live.analyser) analyser = live.analyser;
  else if (mode === "B" && window._bAnalyser && $("audioB") && !$("audioB").paused) analyser = window._bAnalyser;

  if (!analyser) {
    // idle baseline
    specCtx.strokeStyle = "rgba(232,93,24,0.25)";
    specCtx.beginPath();
    specCtx.moveTo(0, h - 6);
    specCtx.lineTo(w, h - 6);
    specCtx.stroke();
    return;
  }
  const bins = analyser.frequencyBinCount;
  if (!specData || specData.length !== bins) specData = new Uint8Array(bins);
  analyser.getByteFrequencyData(specData);

  // log-ish mapping across bins for musical feel
  const bars = 48;
  const gap = 1;
  const barW = (w / bars) - gap;
  for (let i = 0; i < bars; i++) {
    const t0 = i / bars;
    const t1 = (i + 1) / bars;
    // emphasize lower mids slightly via sqrt mapping into bin space
    const b0 = Math.floor(Math.pow(t0, 1.4) * (bins - 1));
    const b1 = Math.max(b0 + 1, Math.floor(Math.pow(t1, 1.4) * (bins - 1)));
    let sum = 0;
    for (let b = b0; b < b1; b++) sum += specData[b];
    const avg = sum / (b1 - b0);
    const bh = (avg / 255) * (h - 4);
    const x = i * (barW + gap);
    const grad = specCtx.createLinearGradient(0, h, 0, h - bh);
    grad.addColorStop(0, "rgba(46,204,90,0.75)");
    grad.addColorStop(0.55, "rgba(240,196,76,0.85)");
    grad.addColorStop(1, "rgba(232,93,24,0.9)");
    specCtx.fillStyle = grad;
    specCtx.fillRect(x, h - bh, barW, bh);
  }
}

