function positionInfoOnVinyl(panel) {
  if (!panel) return;
  // Dead center of the vinyl disc — not the stage (stage includes meters/download and shifts)
  const vinyl =
    document.querySelector(".ring-wrap") ||
    document.getElementById("vinylRing") ||
    document.querySelector(".scrub-wrap") ||
    document.querySelector(".stage");
  if (!vinyl) return;
  const r = vinyl.getBoundingClientRect();
  if (r.width < 8 || r.height < 8) return;
  const cx = r.left + r.width / 2;
  const cy = r.top + r.height / 2;
  panel.style.left = cx + "px";
  panel.style.top = cy + "px";
  panel.style.transform = "translate(-50%, -50%)";
  panel.style.right = "auto";
  panel.style.bottom = "auto";
}

